fn populate_matrix_algebra(
    n: usize,
    d: usize,
    mu: &mut BasicMatrix<GaussianRat>,
    eta: &mut BasicMatrix<GaussianRat>,
) -> Result<(), FrobeniusError> {
    for i in 0..n {
        eta.set(i * n + i, 0, gi(1, 0))?;
        for j in 0..n {
            for k in 0..n {
                mu.set(i * n + k, (i * n + j) * d + j * n + k, gi(1, 0))?;
            }
        }
    }
