    for j in 0..d {
        let inv_ij = inverse
            .get_ref(i, j)
            .map_err(|e| FrobeniusError::Matrix(e.to_string()))?;
        entry = entry + inv_ij * mu.get_ref(k, j * d + a)?;
    }
