/// `W rho W*` for `W = U_n ... U_1`: the state after the declared steps.
pub fn schrodinger_state(
    steps: &[BasicMatrix<GaussianRat>],
    rho: &BasicMatrix<GaussianRat>,
) -> Result<BasicMatrix<GaussianRat>, HeisenbergError> {
