    let a13 = (&a1.0 + &a3.0, &a1.1 + &a3.1);
    let a23 = (&a2.0 + &a3.0, &a2.1 + &a3.1);
    let a123 = (&a12.0 + &a3.0, &a12.1 + &a3.1);

    let norm_sq = |a: &(Rational, Rational)| &a.0 * &a.0 + &a.1 * &a.1;

