    let p13 = norm_sq(&a13);
    let p23 = norm_sq(&a23);
    let p1 = norm_sq(&a1);
    let p2 = norm_sq(&a2);
    let p3 = norm_sq(&a3);

    p123 - p12 - p13 - p23 + p1 + p2 + p3
}

