pub fn identity(dim: usize, label: impl Into<String>) -> Result<Self, KrausError> {
    if dim == 0 {
        return Err(KrausError::EmptySet);
    }
    preflight(dim, 1)?;
    let id_c = CMatrix::identity(dim, dim);
    Ok(Self {
        dim,
        ops: vec![id_c.clone()],
        c_ops: vec![id_c],
