/// Real projection matrix snapshot (n×n row-major) for compatibility.
pub fn real_ops(&self) -> Vec<Vec<Vec<f64>>> {
    self.ops
        .iter()
        .map(|mat| {
            let mut row_vec = vec![vec![0.0; self.dim]; self.dim];
            for i in 0..self.dim {
                for j in 0..self.dim {
                    row_vec[i][j] = mat[(i, j)].re;
