    for (j, c) in polynomial.iter().enumerate() {
        if !c.is_real() {
            return Err(PerturbationError::NonrealEnergy);
        }
        coefficient_series[j] = coefficient_series[j].add(&lagrange.scale(&c.re))?;
    }
