fn build_toric_pairing_matrix(raw_x: &[F2Vector], z: &[F2Vector]) -> Result<F2Matrix, ToricError> {
    let rows = raw_x
        .iter()
        .map(|x| {
            z.iter()
                .map(|z_vec| x.dot(z_vec).map(u8::from).map_err(topology))
                .collect::<Result<Vec<_>, _>>()
