    let z = complex.homology_basis(1).map_err(topology)?;
    let raw_x = complex.cohomology_basis(1).map_err(topology)?;
    if z.len() != 2 || raw_x.len() != 2 || k != 2 {
        return Err(topology("torus first homology must have rank two"));
    }
    Ok((z, raw_x))
}

