fn joint_spectral_basis(
    operators: &[BasicMatrix<Cyc24>],
    d: usize,
) -> Result<Vec<BasicMatrix<Cyc24>>, String> {
    let identity = matrix::identity(d).map_err(|e| e.to_string())?;
