            return BigRational::zero();
        };
        if pivot != col {
            a.swap(col, pivot);
            sign = -sign;
        }
        let piv_val = a[col][col].clone();
        det_val *= &piv_val;
        for r in (col + 1)..4 {
            if a[r][col].is_zero() {
                continue;
            }
            let factor = &a[r][col] / &piv_val;
            for c in col..4 {
                let term = &factor * &a[col][c];
                a[r][c] -= term;
            }
