fn check_step(step: &[Vec<Rational>]) -> Result<usize, StochasticStepError> {
    let n = step.len();
    if n == 0 {
        return Err(StochasticStepError::Empty);
    }
    for (row, entries) in step.iter().enumerate() {
        if entries.len() != n {
