        word: word.to_string(),
    };
    if letters.len() != 2 {
        return Err(bad());
    }
    let parse = |c| match c {
        'I' => Some(Pauli::Identity),
        'X' => Some(Pauli::X),
        'Y' => Some(Pauli::Y),
        'Z' => Some(Pauli::Z),
        _ => None,
    };
    let parsed = letters
        .into_iter()
        .map(parse)
        .collect::<Option<Vec<_>>>()
        .ok_or_else(bad)?;
    let m = pauli_symplectic::pauli_word::<GaussianRat>(&parsed).map_err(|_| bad())?;
    Ok(m)
}

