fn dyadic_roots_are_periodic_across_signed_exponents() {
    for m in 1..=3 {
        let period = 1_i64 << m;
        for power in [i64::MIN, i64::MIN + 1, -25, -1, 0, 1, 25, i64::MAX] {
            let root = dyadic_root_of_unity(m, power);
