    for j in 0..n {
        let c = m[(i, j)];
        k[(i, j)] = c.re;
        k[(i, n + j)] = -c.im;
        k[(n + i, j)] = c.im;
        k[(n + i, n + j)] = c.re;
    }

let eigen = k.symmetric_eigen();
let min_val = eigen
    .eigenvalues
    .iter()
    .copied()
    .fold(f64::INFINITY, f64::min);
