pub const MAX_DIM: usize = 8;
pub const MAX_CELLS: usize = 32;
pub const MAX_JUMPS: usize = 16;
pub const MAX_INPUT_BITS: u64 = 256;

#[derive(Debug, thiserror::Error)]
pub enum QddcError {
    #[error("QDDC contract: {0}")]
    Contract(&'static str),
    #[error(transparent)]
    Operator(#[from] OperatorError),
