        .into_iter()
        .map(|entries| {
            let matrix =
                BasicMatrix::from_row_major(dim, dim, entries).map_err(RationalError::from)?;
            let operator = ExactOperator::try_new(matrix)?;
            operator.check_hermitian()?;
            Ok(operator)
        })
        .collect()
}
