        .zip(b.iter())
        .map(|(ra, rb)| ra.iter().zip(rb.iter()).map(|(&x, &y)| x + y).collect())
        .collect()
}

fn qd_sub(a: &QMatDyn, b: &QMatDyn) -> QMatDyn {
